update public.training_sources set checked_on=date '2026-10-16',updated_at=now() where source_key in ('mlps-asr-2025','normattiva-dlgs81-vigente','inail-informo-carrelli-21','inail-agricoltura-sicurezza','inail-agricoltura-infortuni-2024','inail-vibrazioni');

update public.training_blueprints set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('legal_reviewed_on','2026-10-16','regulatory_basis','D.Lgs. 81/2008 art. 73, comma 5 + ASR 17/04/2025 Parte II punto 8','didactic_candidate','equipment-authored-v3','practical_completion_not_digital',true,'regulatory_verification_required',true,'test_builder_scope','paused_excluded','publication_policy','draft_review_before_linking','catalog_gap_reviewed',true),updated_at=now() where stable_key='equipment_initial';
update public.training_blueprints set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('legal_reviewed_on','2026-10-16','regulatory_basis','ASR 17/04/2025 Parte III punto 6','didactic_candidate','equipment-authored-v3','renewal_interval_months',60,'minimum_minutes',240,'minimum_practical_minutes',240,'practical_completion_not_digital',true,'regulatory_verification','prova pratica + colloquio','test_builder_scope','paused_excluded','publication_policy','draft_review_before_linking'),updated_at=now() where stable_key='equipment_update';
update public.courses set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('candidate_didactic_version','equipment-authored-v3','legal_reviewed_on','2026-10-16','content_review_ready',true,'practical_gate_required',true,'auto_publish',false,'auto_relink',false),updated_at=now() where active=true and metadata->>'blueprint_key' in ('equipment_initial','equipment_update');
update public.training_blueprint_variants set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('candidate_didactic_version','equipment-authored-v3','legal_reviewed_on','2026-10-16','content_review_ready',true,'practical_gate_required',true,'auto_materialize',false),updated_at=now() where blueprint_key in ('equipment_initial','equipment_update');

insert into public.training_blueprint_variants(blueprint_key,variant_key,title,nominal_minutes,status,metadata)
select 'equipment_initial',x.variant_key,x.title,x.minutes,'planned',jsonb_build_object('asr_2025_gap',true,'theory_minutes',x.theory,'practical_minutes',x.practice,'practice_scope',x.scope,'materialized',false,'requires_admin_mapping',true,'legal_reviewed_on','2026-10-16')
from (values
('ple_stabilizers','PLE che operano su stabilizzatori (8h)',480,240,240,'PLE che operano su stabilizzatori'),
('ple_no_stabilizers','PLE che possono operare senza stabilizzatori (8h)',480,240,240,'PLE senza stabilizzatori'),
('gru_torre_low','Gru a torre a rotazione in basso (12h)',720,480,240,'rotazione in basso'),
('gru_torre_high','Gru a torre a rotazione in alto (12h)',720,480,240,'rotazione in alto'),
('carrelli_telescopic','Carrelli semoventi a braccio telescopico (12h)',720,480,240,'carrelli semoventi a braccio telescopico'),
('carrelli_rotating','Carrelli telescopici rotativi (12h)',720,480,240,'carrelli telescopici rotativi'),
('carrelli_extra_functions','Carrelli con funzioni aggiuntive di sollevamento carichi sospesi e persone (14h)',840,480,360,'carrelli con attrezzature intercambiabili'),
('gru_mobile_base','Gru mobili - modulo base (14h)',840,420,420,'gru mobili base'),
('gru_mobile_falcone','Gru mobili con falcone telescopico o brandeggiabile (22h)',1320,660,660,'gru mobili con falcone'),
('mmt_fune','Escavatori a fune (10h)',600,240,360,'escavatori a fune'),
('mmt_loader','Pale caricatrici frontali (10h)',600,240,360,'pale caricatrici frontali'),
('mmt_terna','Terne (10h)',600,240,360,'terne'),
