insert into public.training_blueprint_variants(blueprint_key,variant_key,title,nominal_minutes,status,metadata)
select 'equipment_update',v.variant_key||'_4h','Aggiornamento '||v.title||' (4h)',240,'planned',jsonb_build_object('asr_2025_gap',true,'theory_minutes',0,'practical_minutes',240,'renewal_interval_months',60,'source_initial_variant',v.variant_key,'materialized',false,'requires_admin_mapping',true,'legal_reviewed_on','2026-10-16','assessment','practical_and_interview')
from public.training_blueprint_variants v where v.blueprint_key='equipment_initial' and v.metadata->>'asr_2025_gap'='true'
on conflict (blueprint_key,variant_key) do update set title=excluded.title,nominal_minutes=excluded.nominal_minutes,status=excluded.status,metadata=excluded.metadata,updated_at=now();

with target as (
  select distinct lu.id learning_unit_id,lu.stable_key,lu.title,
    (select max(v.version_number)+1 from public.learning_unit_versions v where v.learning_unit_id=lu.id) target_version,
    (select v.content from public.learning_unit_versions v where v.learning_unit_id=lu.id order by v.version_number desc limit 1) old_content,
    (lu.stable_key like 'update:%') is_update,
    case when lu.stable_key like '%carrelli%' then 'carrelli' when lu.stable_key like '%carroponte%' then 'carroponte' when lu.stable_key like '%cmm%' then 'cmm' when lu.stable_key like '%crf%' then 'crf' when lu.stable_key like '%gru_autocarro%' then 'gru_autocarro' when lu.stable_key like '%gru_torre%' then 'gru_torre' when lu.stable_key like '%mmt%' then 'mmt' when lu.stable_key like '%ple%' then 'ple' when lu.stable_key like '%pompe%' then 'pompe' when lu.stable_key like '%trattori%' then 'trattori' else 'equipment' end family
  from public.courses c join public.course_versions cv on cv.course_id=c.id join public.course_modules cm on cm.course_version_id=cv.id join public.course_module_units cmu on cmu.module_id=cm.id join public.learning_unit_versions linked on linked.id=cmu.unit_version_id join public.learning_units lu on lu.id=linked.learning_unit_id
  where c.active=true and c.metadata->>'blueprint_key' in ('equipment_initial','equipment_update') and cv.version_number=(select max(v.version_number) from public.course_versions v where v.course_id=c.id)
), profiled as (
 select t.*,
   case family when 'ple' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-noleggio','inail-ple-en280-2024') when 'carrelli' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-noleggio','inail-informo-carrelli-21','inail-vibrazioni') when 'trattori' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-noleggio','inail-agricoltura-sicurezza','inail-agricoltura-infortuni-2024','inail-vibrazioni') when 'crf' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-noleggio','inail-agricoltura-sicurezza') when 'carroponte' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-marcate-ce','inail-sollevamento-fisso-2026') when 'mmt' then jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-noleggio','inail-vibrazioni') else jsonb_build_array('mlps-asr-2025','normattiva-dlgs81-vigente','inail-attrezzature-noleggio','inail-attrezzature-marcate-ce') end source_keys
 from target t
), enriched as (
 select p.*,old_content||jsonb_build_object(
   'summary',case when is_update then coalesce(old_content->>'summary','Aggiornamento pratico quinquennale: controlli, configurazione, manovre, anomalie e STOP.') else 'Unità teorico-tecnica su '||title||' per preparare decisioni e prove pratiche sulla macchina reale.' end,
   'detail',coalesce(old_content->>'detail','')||' Collegare sempre teoria, manuale, controlli, configurazione, area di lavoro, interferenze e condizioni di STOP. Il materiale digitale non sostituisce la pratica prevista dall’ASR 2025.',
   'question',case when is_update then 'Se durante la prova pratica cambia una condizione rilevante, qual è la sequenza corretta?' else 'Quali verifiche devono essere concluse prima della manovra sulla macchina reale?' end,
   'question_explanation',case when is_update then 'STOP, messa in sicurezza, rivalutazione, coinvolgimento dei soggetti necessari e ripresa solo dopo ripristino verificato.' else 'Identificare macchina/configurazione, limiti, controlli, area e interferenze; la pratica inizia solo con condizioni coerenti con manuale e procedura.' end,
   'common_errors',jsonb_build_array('Saltare i controlli pre-uso.','Compensare una condizione non sicura con maggiore attenzione.','Accettare persone nella zona pericolosa.','Usare accessori/configurazioni senza verificarne compatibilità e portata.','Riavviare dopo anomalia senza chiarirne la causa.'),
   'operational',jsonb_build_object('before',jsonb_build_array('Identifica macchina, variante, accessori e configurazione.','Consulta manuale, limiti/diagrammi e procedura.','Esegui controlli pre-uso.','Valuta area, percorso e interferenze.'),'during',jsonb_build_array('Mantieni persone fuori dalla zona pericolosa.','Esegui movimenti progressivi entro i limiti.','Mantieni controllo di stabilità, visuale e percorso.','Ferma la manovra se cambia una condizione rilevante.'),'after',jsonb_build_array('Metti la macchina nella configurazione di fine lavoro.','Esegui controlli post-uso.','Segnala anomalie e impedisci uso non autorizzato.'),'if_problem',jsonb_build_array('STOP: non neutralizzare allarmi/protezioni.','Metti in sicurezza macchina e area.','Richiedi assistenza/manutenzione quando necessario.','Riprendi solo dopo ripristino verificato.'),'who_to_involve',jsonb_build_array('Preposto o referente operativo','Assistente/segnalatore se previsto','Manutenzione/assistenza tecnica','RSPP o gestore area per criticità/interferenze'),'stop_conditions',jsonb_build_array('Condizione non valutabile in sicurezza.','Protezione/dispositivo essenziale non funzionante.','Persona nella zona pericolosa.','Anomalia strutturale o funzionale.')),
   'practical_reference',jsonb_build_object('course_practice_required',true,'unit_is_practical',is_update,'digital_completion',false,'purpose',case when is_update then 'mandatory_practical_update_reference' else 'theory_preparation_and_practical_debrief' end,'family',family,'required_machine_or_equivalent','Pratica con attrezzatura coerente con specifica abilitazione/variante ASR 2025.'),
   'scope_boundary','Materiale didattico e di preparazione/debriefing per abilitazione ex art. 73, comma 5. Non sostituisce parte pratica, manuale del fabbricante, verifiche finali o procedure aziendali.',
   'verification',jsonb_build_object('regulatory_verification_required',true,'test_builder_excluded',true,'final_assessment_in_lu',false,'practical_note','Prova pratica finale sulla specifica attrezzatura/variante.','update_note','Aggiornamento: minimo 4 ore di parte pratica; prova pratica e colloquio.'),
   'formative_check',jsonb_build_object('question','Qual è la risposta corretta a una condizione che non è più sotto controllo?','explanation','Fermare, mettere in sicurezza, rivalutare e riprendere solo dopo ripristino verificato.','formative_only',true,'test_builder_excluded',true),
   'didactic_version','equipment-authored-v3','source_keys',source_keys,'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16','normative_validation','D.Lgs. 81/2008 art.73 + ASR 17/04/2025','reuse_policy','reference_and_original_rewrite'),'quality',coalesce(old_content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true,'practical_gate_explicit',true,'scope_boundary_explicit',true,'equipment_specific',true),'final_assessment',false,'test_builder_excluded',true
 ) content_new from profiled p
), final_content as (
 select e.*,e.content_new||jsonb_build_object('evidence_sources',(select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from jsonb_array_elements_text(e.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key)) content_final from enriched e
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,target_version,'draft',content_final,md5(content_final::text),null from final_content
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

with authored as (select lu.id learning_unit_id,luv.content->'source_keys' source_keys from public.learning_units lu join public.learning_unit_versions luv on luv.learning_unit_id=lu.id where luv.content->>'didactic_version'='equipment-authored-v3' and luv.status='draft')
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select a.learning_unit_id,sk.source_key,'authored_evidence_v3','Fonte per validazione normativa/tecnica della versione equipment-authored-v3.',date '2026-10-16',jsonb_build_object('didactic_version','equipment-authored-v3','reuse_policy','reference_and_original_rewrite') from authored a cross join lateral jsonb_array_elements_text(a.source_keys) sk(source_key) join public.training_sources ts on ts.source_key=sk.source_key
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;

do $$ declare n int; links int; bad int; begin
 select count(*) into n from public.learning_unit_versions where content->>'didactic_version'='equipment-authored-v3' and status='draft'; if n<>63 then raise exception 'expected 63 equipment-authored-v3 drafts, got %',n; end if;
 select count(*) into links from public.course_module_units cmu join public.learning_unit_versions luv on luv.id=cmu.unit_version_id where luv.content->>'didactic_version'='equipment-authored-v3'; if links<>0 then raise exception 'equipment authored drafts unexpectedly linked: %',links; end if;
 select count(*) into bad from public.learning_unit_versions luv where luv.content->>'didactic_version'='equipment-authored-v3' and (luv.content->'quality'->>'teacher_ready' is distinct from 'true' or luv.content->'quality'->>'learner_ready' is distinct from 'true' or luv.content->'quality'->>'question_has_explanation' is distinct from 'true' or luv.content->'quality'->>'test_builder_excluded' is distinct from 'true' or luv.content->'quality'->>'practical_gate_explicit' is distinct from 'true' or luv.content->>'final_assessment' is distinct from 'false' or luv.content->'practical_reference'->>'digital_completion' is distinct from 'false'); if bad<>0 then raise exception 'quality assertions failed for % units',bad; end if;
end $$;